ELICE_IMAGE_B64 = ""

def play_audio(sound_type):
    if st.session_state.get("enable_audio", True):
        js = ""
        if sound_type == "heartbeat":
            js = """<script>
            var ctx = new (window.AudioContext || window.webkitAudioContext)();
            function playBeat() {
                try {
                    var now = ctx.currentTime;
                    var osc1 = ctx.createOscillator();
                    var gain1 = ctx.createGain();
                    osc1.connect(gain1); gain1.connect(ctx.destination);
                    osc1.frequency.setValueAtTime(60, now);
                    gain1.gain.setValueAtTime(0.3, now);
                    gain1.gain.exponentialRampToValueAtTime(0.001, now + 0.12);
                    osc1.start(now); osc1.stop(now + 0.12);

                    var osc2 = ctx.createOscillator();
                    var gain2 = ctx.createGain();
                    osc2.connect(gain2); gain2.connect(ctx.destination);
                    osc2.frequency.setValueAtTime(50, now + 0.18);
                    gain2.gain.setValueAtTime(0.25, now + 0.18);
                    gain2.gain.exponentialRampToValueAtTime(0.001, now + 0.32);
                    osc2.start(now + 0.18); osc2.stop(now + 0.32);
                } catch(e){}
            }
            playBeat();
            window.hbInterval = setInterval(playBeat, 1400);
            </script>"""
        elif sound_type == "stop_heartbeat":
            js = """<script>
            if (window.hbInterval) { clearInterval(window.hbInterval); }
            </script>"""
        elif sound_type == "correct":
            js = """<script>
            var ctx = new (window.AudioContext || window.webkitAudioContext)();
            [523.25, 659.25, 783.99, 1046.50].forEach(function(freq, idx) {
                var osc = ctx.createOscillator();
                var gain = ctx.createGain();
                osc.connect(gain); gain.connect(ctx.destination);
                osc.frequency.setValueAtTime(freq, ctx.currentTime + idx*0.1);
                gain.gain.setValueAtTime(0.2, ctx.currentTime + idx*0.1);
                gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + idx*0.1 + 0.25);
                osc.start(ctx.currentTime + idx*0.1);
                osc.stop(ctx.currentTime + idx*0.1 + 0.25);
            });
            </script>"""
        elif sound_type == "wrong":
            js = """<script>
            var ctx = new (window.AudioContext || window.webkitAudioContext)();
            [220, 196].forEach(function(freq, idx) {
                var osc = ctx.createOscillator();
                var gain = ctx.createGain();
                osc.connect(gain); gain.connect(ctx.destination);
                osc.frequency.setValueAtTime(freq, ctx.currentTime + idx*0.15);
                gain.gain.setValueAtTime(0.3, ctx.currentTime + idx*0.15);
                gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + idx*0.15 + 0.3);
                osc.start(ctx.currentTime + idx*0.15);
                osc.stop(ctx.currentTime + idx*0.15 + 0.3);
            });
            </script>"""
        elif sound_type == "victory":
            js = """<script>
            var ctx = new (window.AudioContext || window.webkitAudioContext)();
            [440, 554.37, 659.25, 880].forEach(function(freq, idx) {
                var osc = ctx.createOscillator();
                var gain = ctx.createGain();
                osc.connect(gain); gain.connect(ctx.destination);
                osc.frequency.setValueAtTime(freq, ctx.currentTime + idx*0.2);
                gain.gain.setValueAtTime(0.3, ctx.currentTime + idx*0.2);
                gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + idx*0.2 + 0.5);
                osc.start(ctx.currentTime + idx*0.2);
                osc.stop(ctx.currentTime + idx*0.2 + 0.5);
            });
            </script>"""
        if js:
            components.html(js, height=0, width=0)

